package com.codearena.problem;
import com.codearena.common.api.ApiResponse; import jakarta.validation.constraints.*; import java.util.*; import org.springframework.http.*; import org.springframework.lang.NonNull; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1/problems") public class ProblemController { final ProblemRepository repo; final TagRepository tags; ProblemController(ProblemRepository r,TagRepository t){repo=r;tags=t;} @GetMapping ApiResponse<List<Problem>> all(){return ApiResponse.of(repo.findByPublishedTrue());} @GetMapping("/{id}") ApiResponse<Problem> one(@PathVariable @NonNull UUID id){return ApiResponse.of(repo.findById(id).filter(p->p.published).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND)));} record Create(@NotBlank @Size(max=200) String title,@NotBlank String description,
String difficulty,@NotEmpty Set<String> supportedLanguages,Set<String> tags,Integer timeLimitMs,Integer memoryLimitMb){} @PostMapping @PreAuthorize("hasAnyRole('TEACHER','ADMIN','SUPER_ADMIN')") @ResponseStatus(HttpStatus.CREATED) ApiResponse<Problem> create(@AuthenticationPrincipal String uid,@RequestBody @jakarta.validation.Valid Create c){var p=new Problem();p.authorId=UUID.fromString(uid);p.title=c.title;p.slug=slug(c.title);p.description=c.description;p.difficulty=c.difficulty==null?"EASY":c.difficulty.toUpperCase(Locale.ROOT);p.supportedLanguages=c.supportedLanguages;p.tags=new HashSet<>();if(c.tags!=null)for(String label:c.tags){var name=label.trim();if(!name.isEmpty()){var tag=tags.findByNameIgnoreCase(name).orElseGet(()->{var t=new Tag();t.name=name;t.slug=name.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+","-");return tags.save(t);});p.tags.add(tag);}}if(c.timeLimitMs!=null)p.timeLimitMs=c.timeLimitMs;if(c.memoryLimitMb!=null)p.memoryLimitMb=c.memoryLimitMb;return ApiResponse.of(repo.save(p));}
private String slug(String title){var base=title.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+","-").replaceAll("(^-|-$)","");return base+"-"+UUID.randomUUID().toString().substring(0,8);}
}
